let theShader;

function preload(){
  theShader = loadShader('https://openprocessing.org/sketch/1239166/files/shader.vert', 'shader.frag');
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
}

function draw() {
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", millis() / 1000.0);

  quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

